-- =====================================================================
-- Script DML: Carga Inicial de Dados (FASTCOOKING)
-- =====================================================================

-- 1. Restaurantes
ON CONFLICT ("idRestaurante") DO NOTHING;

-- 2. Usuários
ON CONFLICT ("idUsuario") DO NOTHING;

-- 3. Mesas
ON CONFLICT ("idMesa") DO NOTHING;

-- 4. Estoque
ON CONFLICT ("idEstoque") DO NOTHING;

-- 5. Cardápio
ON CONFLICT ("idCardapio") DO NOTHING;

-- 6. Ficha Técnica
ON CONFLICT ("idFichaTecnica") DO NOTHING;

-- 7. Pedidos
ON CONFLICT ("idPedido") DO NOTHING;

-- 8. Itens de Pedido
ON CONFLICT ("idItemPedido") DO NOTHING;

-- 9. Pagamento
ON CONFLICT ("idPagamento") DO NOTHING;